<script setup lang="ts">
import { ArrowRight, ArrowUpRight, CornerDownRight } from '@lucide/vue'
import { computed, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import EntityModelDiagram from '../components/model/EntityModelDiagram.vue'
import SpatialDetailMap from '../components/map/SpatialDetailMap.vue'
import EvidenceList from '../components/evidence/EvidenceList.vue'
import SourceDrawer from '../components/evidence/SourceDrawer.vue'
import ServiceBadge from '../components/common/ServiceBadge.vue'
import { useDataStore } from '../stores/data'
import { dateLabel, factLevelLabel, fieldLabel, locationLabel, profileReviewLabel } from '../services/labels'
import { createEntityModel, modelViews, type ModelViewId } from '../services/entityModel'
import type { SourceRecord } from '../types/data'
const data = useDataStore(); const route = useRoute(); const router = useRouter()
const source = ref<SourceRecord | null>(null); const showJson = ref(false)
const selectedId = computed({ get: () => typeof route.query.site === 'string' ? route.query.site : 'crs-r47589-008', set: id => { showJson.value = false; void router.replace({ query: { ...route.query, site: id, component: undefined } }) } })
const profile = computed(() => data.profiles.find(item => item.site_id === selectedId.value))
const site = computed(() => data.sites.find(item => item.properties.site_id === selectedId.value))
const facts = computed(() => profile.value?.profile_facts.filter(fact => !fact.field.startsWith('description_')) ?? [])
const evidence = computed(() => data.evidenceRows.filter(row => row.entity_id === selectedId.value))
const view = computed({ get: () => modelViews.find(item => item.id === route.query.view)?.id ?? 'space', set: (value: ModelViewId) => { void router.replace({ query: { ...route.query, view: value } }) } })
const selectedAnchor = computed({ get: () => typeof route.query.component === 'string' ? route.query.component : 'main', set: id => { void router.replace({ query: { ...route.query, component: id === 'main' ? undefined : id } }) } })
const modelJson = computed(() => profile.value && site.value ? JSON.stringify(createEntityModel(profile.value, site.value, data.meta!.review_source_hashes), null, 2) : '')
function openSource(id: string) { source.value = data.sourceRegistry?.sources[id] ?? null }
function locate(id: string) { void router.replace({ query: { ...route.query, view: 'space', component: id } }) }
function downloadModel() {
  if (!profile.value) return
  const url = URL.createObjectURL(new Blob([modelJson.value], { type: 'application/json;charset=utf-8' }))
  const link = document.createElement('a'); link.href = url; link.download = profile.value.site_id + '-model.json'; link.click()
  window.setTimeout(() => URL.revokeObjectURL(url), 1000)
}
</script>
<template>
  <div v-if="data.meta" class="page model-page"><div class="page-intro"><div><span class="eyebrow cyan">一级成果 / 模型理解与运用</span><h2>用真实实体理解开放系统模型</h2><p>以同一个基地的属性、空间、组成关系和证据，展示本项目的一级描述模型。</p></div></div>
  <section class="panel entity-explorer" aria-label="实体模型浏览"><div class="explorer-heading"><div><h3>查看一个实际实体</h3><p class="muted">点击模型视角，沿着来源查看数据如何联系。</p></div><label for="model-site">选择基地<select id="model-site" v-model="selectedId"><option v-for="item in data.profiles" :key="item.site_id" :value="item.site_id">{{ String(item.source_record_no).padStart(2,'0') }} · {{ item.canonical_name }}</option></select></label></div>
  <template v-if="profile && site"><div class="entity-meta"><span>{{ locationLabel(site.properties.location_label) }}</span><ServiceBadge :value="site.properties.service_component" /><span class="tag derived">{{ profileReviewLabel(profile.review_status) }}</span><RouterLink :to="{ path: '/map', query: { site: profile.site_id } }">在地图中查看</RouterLink><RouterLink :to="{ path: '/sites/' + profile.site_id }">查看详细画像 <ArrowRight :size="15" aria-hidden="true" /></RouterLink></div>
  <EntityModelDiagram v-model:view="view" :profile="profile" :property-count="facts.length" :evidence-count="evidence.length" />
  <div class="model-view" :aria-label="modelViews.find(item => item.id === view)?.label + '模型视角'">
    <template v-if="view === 'space'"><SpatialDetailMap v-model:selected-id="selectedAnchor" :profile="profile" :site="site" @source="openSource" /></template>
    <template v-else-if="view === 'attributes'"><div class="view-heading"><h3>属性与来源</h3><span>{{ facts.length }} 项有出处的描述</span></div><div class="model-facts"><article v-for="fact in facts" :key="fact.field"><span class="tag" :class="fact.fact_level === 'SOURCE_FACT' ? 'source' : 'derived'">{{ factLevelLabel(fact.fact_level) }}</span><div><strong>{{ fieldLabel(fact.field) }}</strong><p>{{ fact.value }}</p><div class="fact-sources"><button v-for="id in fact.source_ids" :key="id" type="button" @click="openSource(id)">{{ data.sourceRegistry?.sources[id]?.title ?? id }} <ArrowUpRight :size="14" aria-hidden="true" /></button></div></div></article></div></template>
    <template v-else-if="view === 'relations'"><div class="view-heading"><h3>组成与关联关系</h3><span>{{ profile.components.length }} 条具名关系</span></div><p class="muted">以下对象通过保存的关系和出处连接到 {{ profile.canonical_name }}。</p><div v-if="profile.components.length" class="relation-list"><article v-for="component in profile.components" :key="component.component_id"><CornerDownRight class="relation-node" :size="20" aria-hidden="true" /><div><strong>{{ component.name }}</strong><p>{{ component.relationship }}</p><small class="muted">{{ component.location ? '有独立定位与空间证据' : '按来源保留文字关系' }}</small><div class="relation-tools"><button v-if="component.location" type="button" class="secondary-btn" @click="locate(component.component_id)">在空间视角定位</button><button v-for="id in component.source_ids" :key="id" type="button" class="secondary-btn" @click="openSource(id)">关系出处 · {{ data.sourceRegistry?.sources[id]?.title ?? id }} <ArrowUpRight :size="14" aria-hidden="true" /></button></div></div></article></div><div v-else class="empty-message"><strong>本记录没有独立具名关系</strong><p>可以查看属性、空间与证据，或切换到多设施示例。</p></div></template>
    <template v-else><div class="view-heading"><h3>字段证据与审核版本</h3><span>{{ evidence.length }} 条字段证据</span></div><div class="review-thread"><span>来源归档</span><ArrowRight :size="15" aria-hidden="true" /><span>当前字段与模型</span><ArrowRight :size="15" aria-hidden="true" /><span>内容指纹</span><ArrowRight :size="15" aria-hidden="true" /><span>来源审核</span></div><p class="muted" v-if="profile.review_record">当前记录由 {{ profile.review_record.reviewer }}（AI代理）于 {{ dateLabel(profile.review_record.reviewed_at) }} 审核；变更内容或来源后，原审核指纹会失效。</p><EvidenceList :rows="evidence" @source="openSource" /></template>
  </div>
  <details class="model-technical"><summary>当前实体的结构化接口与版本</summary><div class="json-actions"><button type="button" class="secondary-btn" :aria-expanded="showJson" @click="showJson = !showJson">{{ showJson ? '收起' : '查看' }}当前实体模型 JSON</button><button type="button" class="secondary-btn" @click="downloadModel">下载完整实体 JSON</button></div><template v-if="showJson"><p class="muted json-note">完整模型 {{ modelJson.length.toLocaleString() }} 字符，预览前 {{ Math.min(modelJson.length,12000).toLocaleString() }} 字符；下载保留全部字段与几何。</p><pre class="model-json">{{ modelJson.slice(0,12000) }}</pre></template><div class="version-list"><div v-for="(hash,name) in data.meta.review_source_hashes" :key="name"><strong translate="no">{{ name }}</strong><code translate="no">{{ hash }}</code></div></div></details></template>
  <div v-else class="empty-message"><strong>未找到当前实体</strong><p>请在上方选择已有记录。</p><button type="button" class="secondary-btn" @click="selectedId = 'crs-r47589-008'">恢复Kitsap示例</button></div></section>
  <details class="panel model-concepts"><summary>公开概念与本项目的理解和运用</summary><p class="concept-scope">{{ data.meta.open_system_model.scope }}</p><div class="concept-grid"><article v-for="concept in data.meta.open_system_model.concepts" :key="concept.title"><h3>{{ concept.title }}</h3><p>{{ concept.explanation }}</p><p class="implementation">{{ concept.implementation }}</p><div class="fact-sources"><button v-for="id in concept.source_ids" :key="id" type="button" @click="openSource(id)">{{ data.sourceRegistry?.sources[id]?.title ?? id }} <ArrowUpRight :size="14" aria-hidden="true" /></button></div></article></div><p class="muted">依据公开说明和联盟通用概念建立项目映射；专用模型完整规范未取得，当前数据合同为本项目实现。</p></details>
  <details class="panel update-cycle" aria-label="来源更新与版本审核"><summary>来源更新与版本审核</summary><div class="panel-heading"><div><h3>来源更新与版本审核</h3><small>本次资料发布：{{ dateLabel(data.meta.generated_at, true) }}</small></div><span class="tag derived">可追溯快照</span></div><ol><li><strong>归档来源</strong><p>保存文献、查询响应、获取时间和原始字节指纹。</p></li><li><strong>更新数字描述</strong><p>将可信事实、地点和关系写入既有画像与GIS合同。</p></li><li><strong>重新审核</strong><p>新内容使旧审核失效，由Codex核对当前版本。</p></li><li><strong>校验并发布</strong><p>通过合同、出处、指纹及构建检查，发布可运行成果。</p></li></ol><p class="scope-copy">本级描述公开参考快照；传感测量、物理控制与实时状态需要另外的可信输入和验证。</p></details><SourceDrawer :source="source" @close="source = null" /></div>
</template>
<style scoped>
.model-page{display:grid;gap:20px}.model-page .page-intro{margin:10px 0 0}.model-kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.model-kpis>div{padding:18px 21px;background:#fff;border:1px solid var(--line);border-radius:11px;display:flex;align-items:center;gap:17px}.model-kpis strong{font-size:30px;color:var(--cyan)}.model-kpis span{font-size:13px;color:var(--muted)}.explorer-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.explorer-heading h3,.view-heading h3,.update-cycle h3{margin:0;font-size:20px}.explorer-heading p{font-size:13px;margin:7px 0 0}.explorer-heading label{display:grid;gap:7px;max-width:100%;font-size:13px}.explorer-heading select{max-width:min(430px,100%);width:100%}.entity-meta{display:flex;align-items:center;gap:13px;flex-wrap:wrap;font-size:13px;padding:20px 0}.entity-meta>a{margin-left:auto;text-decoration:none}.model-view{margin-top:24px}.view-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}.view-heading>span{font-size:13px;color:var(--muted)}.model-facts article{display:grid;grid-template-columns:95px minmax(0,1fr);gap:15px;padding:18px 0;border-top:1px solid var(--line);align-items:start}.model-facts p{margin:9px 0;line-height:1.9;overflow-wrap:anywhere}.fact-sources{display:flex;flex-wrap:wrap;gap:7px}.fact-sources button{font-size:12px;text-align:left;max-width:100%;overflow-wrap:anywhere;border:1px solid #cfe1df;border-radius:6px;padding:7px 10px;color:var(--cyan);background:#eef7f5;line-height:1.6}.relation-list{display:grid;gap:12px}.relation-list article{display:flex;gap:14px;padding:18px;background:#f3f8f9;border:1px solid var(--line);border-radius:9px}.relation-node{font-size:24px;color:#6c9d9f}.relation-list article>div{min-width:0}.relation-list p{font-size:14px;line-height:1.8;overflow-wrap:anywhere}.relation-tools{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.relation-tools button{font-size:12px;max-width:100%;overflow-wrap:anywhere}.review-thread{display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:13px;padding:15px;background:#eef7f5;border-radius:9px}.review-thread span{padding:6px 8px;border:1px solid #bfdbd5;border-radius:5px;background:#fff}.review-thread svg{color:var(--muted)}.model-technical{margin-top:25px;border-top:1px solid var(--line);padding-top:18px}.model-technical summary{font-size:14px;color:var(--muted)}.json-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.json-note{font-size:12px}.model-json{white-space:pre-wrap;overflow-wrap:anywhere;max-height:350px;overflow:auto;padding:18px;background:#f2f6f8;border:1px solid var(--line);border-radius:8px;font-size:12px;line-height:1.7}.version-list{display:grid;gap:10px;margin-top:23px}.version-list>div{display:grid;grid-template-columns:160px minmax(0,1fr);gap:12px;font-size:12px}.version-list code{color:var(--muted);overflow-wrap:anywhere}.model-concepts summary{font-size:18px;font-weight:650}.concept-scope{color:var(--muted);font-size:14px;line-height:1.8}.concept-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;margin:20px 0}.concept-grid article{padding:18px;border:1px solid var(--line);border-radius:9px}.concept-grid h3{font-size:17px;margin:0}.concept-grid p{font-size:14px;line-height:1.8}.implementation{color:var(--cyan)}.update-cycle ol{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;padding-left:23px}.update-cycle li{padding-left:4px;font-size:14px}.update-cycle li p{font-size:13px;color:var(--muted);line-height:1.8}.scope-copy{font-size:13px;color:var(--muted);border-top:1px solid var(--line);padding-top:16px}.model-page strong,.model-page p{overflow-wrap:anywhere}
.entity-meta>a{margin-left:0}.entity-meta>a:first-of-type{margin-left:auto}.update-cycle summary{font-weight:650}.update-cycle .panel-heading{margin-top:20px}
@media(max-width:1100px){.model-kpis>div{display:grid;gap:6px}.update-cycle ol{grid-template-columns:1fr 1fr}}
@media(max-width:760px){.model-kpis{gap:8px}.model-kpis>div{padding:14px 10px}.model-kpis strong{font-size:23px}.model-kpis span{font-size:12px;line-height:1.6}.explorer-heading label{width:100%}.explorer-heading select{width:100%}.entity-meta{gap:9px}.entity-meta>a{margin-left:0;width:100%}.model-facts article{grid-template-columns:1fr;gap:10px}.model-facts article>.tag{justify-self:start}.model-facts p{font-size:14px}.concept-grid,.update-cycle ol{grid-template-columns:1fr}.version-list>div{grid-template-columns:1fr;gap:6px}.relation-list article{padding:15px}.view-heading h3{font-size:18px}.model-concepts summary{font-size:16px}.update-cycle h3{font-size:18px}.review-thread{gap:7px}.review-thread svg{display:none}}
</style>
